const assert = require('node:assert/strict');
const { ProfileService } = require('../.build/service');

const dup = (p) => ({ displayName: p.displayName, tags: p.tags.slice() });

function fresh() {
  return new ProfileService({ displayName: 'before', tags: ['old'] });
}

// --- happy paths -----------------------------------------------------------
{
  const s = fresh();
  const same = s.patch({});
  assert.equal(same, s.profile);
  assert.deepEqual(dup(same), { displayName: 'before', tags: ['old'] });

  assert.deepEqual(dup(s.patch({ displayName: ' after ' })), { displayName: 'after', tags: ['old'] });
  assert.deepEqual(dup(s.patch({ tags: [' a ', 'b'] })), { displayName: 'after', tags: ['a', 'b'] });
  assert.deepEqual(dup(s.patch({ displayName: null })), { displayName: null, tags: ['a', 'b'] });
  assert.deepEqual(dup(s.patch({ tags: null })), { displayName: null, tags: [] });
  assert.deepEqual(dup(s.patch({ tags: [] })), { displayName: null, tags: [] });
  assert.deepEqual(dup(s.patch({ displayName: 'x', tags: ['1', '2', '3', '4', '5'] })), {
    displayName: 'x',
    tags: ['1', '2', '3', '4', '5'],
  });
  assert.deepEqual(dup(s.patch({ displayName: 'a'.repeat(40) })).displayName, 'a'.repeat(40));
  assert.deepEqual(dup(s.patch({ tags: ['b'.repeat(12)] })).tags, ['b'.repeat(12)]);
}

// --- null-prototype input --------------------------------------------------
{
  const s = fresh();
  const input = Object.create(null);
  input.displayName = '  nul  ';
  input.tags = [' t '];
  assert.deepEqual(dup(s.patch(input)), { displayName: 'nul', tags: ['t'] });
}

// --- non-plain inputs rejected --------------------------------------------
for (const bad of [null, undefined, 0, 1, NaN, true, 'x', Symbol('s'), [], ['displayName'], () => {}, new Date(), new Map(), new (class { displayName = 'x' })(), Object.create({ displayName: 'x' })]) {
  const s = fresh();
  assert.throws(() => s.patch(bad), { message: 'invalid profile' }, String(bad));
  assert.deepEqual(dup(s.profile), { displayName: 'before', tags: ['old'] });
}

// --- unknown keys rejected (including symbols / non-enumerable) ------------
{
  const inputs = [{ other: 1 }, { displayName: 'x', tags: ['a'], extra: true }];
  const sym = { displayName: 'x' };
  sym[Symbol('hidden')] = 1;
  inputs.push(sym);
  const hidden = Object.defineProperty({ displayName: 'x' }, 'secret', { value: 1, enumerable: false });
  inputs.push(hidden);
  for (const input of inputs) {
    const s = fresh();
    assert.throws(() => s.patch(input), { message: 'invalid profile' });
    assert.deepEqual(dup(s.profile), { displayName: 'before', tags: ['old'] });
  }
}

// --- invalid displayName values -------------------------------------------
for (const bad of ['', '   ', 'a'.repeat(41), 123, 0, false, {}, [], ['x'], Symbol('s'), new String('x'), undefined]) {
  const s = fresh();
  assert.throws(() => s.patch({ displayName: bad }), { message: 'invalid profile' }, String(bad));
  assert.deepEqual(dup(s.profile), { displayName: 'before', tags: ['old'] });
}

// --- invalid tags values ---------------------------------------------------
for (const bad of [
  ['a', 'a'],            // duplicate after trim
  [' a', 'a'],           // duplicate after trim
  ['a', 'b', 'c', 'd', 'e', 'f'], // too many
  ['', 'a'],             // empty after trim
  ['   '],               // empty after trim
  ['a'.repeat(13)],      // too long after trim
  [1], [true], [null], [{}], [['a']], // non-strings, no coercion
  'a', 1, {}, undefined, // not array / null
]) {
  const s = fresh();
  assert.throws(() => s.patch({ tags: bad }), { message: 'invalid profile' }, JSON.stringify(bad));
  assert.deepEqual(dup(s.profile), { displayName: 'before', tags: ['old'] });
}

// --- atomicity: valid displayName + invalid tags leaves everything --------
{
  const s = fresh();
  assert.throws(() => s.patch({ displayName: 'new', tags: ['ok', 'ok'] }), { message: 'invalid profile' });
  assert.deepEqual(dup(s.profile), { displayName: 'before', tags: ['old'] });
}

// --- input object not mutated; no aliasing of caller's tags array ---------
{
  const s = fresh();
  const input = { displayName: '  after  ', tags: ['  a  ', 'b'] };
  const inputSnapshot = { displayName: '  after  ', tags: ['  a  ', 'b'] };
  const result = s.patch(input);
  assert.deepEqual(input, inputSnapshot);
  assert.notEqual(result, input);
  assert.notEqual(result.tags, input.tags);
  input.tags.push('mutated');
  result.tags.push('also-mutated');
  assert.deepEqual(dup(s.profile), { displayName: 'after', tags: ['a', 'b', 'also-mutated'] });
  assert.deepEqual(input.tags, ['  a  ', 'b', 'mutated']);
}

// --- clearing vs absent: stored array identity ----------------------------
{
  const s = fresh();
  const before = s.profile.tags;
  s.patch({ displayName: 'x' });
  assert.equal(s.profile.tags, before);
  s.patch({ tags: [] });
  assert.notEqual(s.profile.tags, before);
  assert.deepEqual(s.profile.tags, []);
}

console.log('contract checks passed');

